// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, 1 ether);

        // Lock in a guess at block B.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);
        uint256 target = block.number + 1;

        // Rule: one block later (block B+1), the target block has NOT yet passed,
        // so settle() must revert. The reference stores B+1 and needs block.number > B+1;
        // the mutant stores B, so at B+1 it proceeds.
        vm.roll(target);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok, "settle succeeded before the recorded target block passed");
    }
}
